// GENERATED by packages/ai/scripts/build-slot-sequences.ts from skills/*.md. Do not edit.
// Run `pnpm --filter @motionpop/ai skills:build` after changing a skill; slot-sequences.test.ts
// fails when this file is out of date.

export const SLOT_SEQUENCES: Readonly<Record<string, string>> = {
  'brand-sting':
    '- 0–30%: brand shape/colour wipe in\n- 30–60%: logo or name resolves (mask reveal) on the spoken name\n- 60–85%: tagline or CTA slides in\n- 85–100%: quick hold, crisp exit',
  'calm-explanation':
    '- 0–20%: eyebrow label enters\n- 20–60%: headline words reveal with gentle stagger\n- 60–75%: highlighter swipe on the key phrase at the spoken key word\n- 75–100%: subline fades in; long hold',
  'contrast-split':
    '- 0–20%: frame splits (vertical in 16:9, horizontal in 9:16); side A label enters\n- 20–45%: side A value/visual builds\n- 45–75%: side B builds and lands on the key word, visibly bigger/smaller\n- 75–100%: difference callout (e.g. "3× more") in accent; hold',
  'countdown-ranking':
    '- 0–10%: title ("The 3 biggest…") enters\n- 10–75%: items appear from lowest to highest rank, each landing on its spoken name\n- 75–90%: number one gets accent fill + slight scale (1.00 → 1.04)\n- 90–100%: hold',
  'journey-along-a-timeline':
    '- 0–15%: timeline line draws across the frame\n- 15–80%: events appear in order as dots + labels, each landing on its spoken date; camera tracks along\n- 80–100%: final event emphasised in accent; hold',
  'shocking-stat-reveal':
    '- 0–15%: small context line enters (muted, eyebrow style)\n- 15–55%: the number counts up with a decisive ease-out and lands exactly on the spoken number word\n- 55–75%: accent colour/highlighter swipe on the final value; camera push settles\n- 75–92%: label slides in under the number; hold\n- 92–100%: fast exit (60% of entrance duration)',
  'slow-build-trend':
    '- 0–15%: title and axes fade in, baseline draws\n- 15–70%: data builds left to right (line draws on / bars grow in sequence), steady pace\n- 70–80%: end point or highest bar emphasised at the key spoken word (dot pulse or accent fill)\n- 80–100%: value label and optional annotation; hold',
  'zoom-from-world-to-place':
    '- 0–15%: world (or continent) view fades in, calm\n- 15–60%: smooth camera move to the target (in-out ease), settling exactly on the spoken place name\n- 60–75%: country fill fades to accent, pin drops with a small ripple\n- 75–100%: label with leader line; optional route arc draws; hold',
};

/** The "Shot sequence" text of a voiceover skill, or '' for an unknown id. */
export function shotSequenceOf(skillId: string): string {
  return Object.hasOwn(SLOT_SEQUENCES, skillId) ? (SLOT_SEQUENCES[skillId] ?? '') : '';
}
